// Video files the Videos spec uploads into its own scratch directory. Real containers and codecs (not hand-rolled
// bytes) so the library probes them, the browser plays the MP4 as it is and the MKV goes through the remux worker.

// 64x64 H.264, 320 s at 1 fps, no audio: long enough to be resumable (a position is kept only for a video of
// five minutes or more), and still a few kilobytes. Generated once with
// `ffmpeg -f lavfi -i testsrc=size=64x64:rate=1:duration=320 -c:v libx264 -profile:v main -pix_fmt yuv420p -crf 45
// -g 20 -bf 0 -movflags +faststart -an`.
export const VIDEOS_MP4_BYTES = Buffer.from(
	"",
	"base64"
)

// 64x64 H.264 at 5 fps with a mono AAC tone, 12 s, in Matroska: no browser plays it as it is here, so it streams
// through the remux worker into MediaSource. Generated once with
// `ffmpeg -f lavfi -i testsrc=size=64x64:rate=5:duration=12 -f lavfi -i sine=frequency=440:sample_rate=22050:duration=12
// -c:v libx264 -profile:v main -pix_fmt yuv420p -crf 45 -g 10 -bf 0 -c:a aac -b:a 12k -ac 1 -shortest`.
export const VIDEOS_MKV_BYTES = Buffer.from(
	"",
	"base64"
)
